export const annuityGuaranteeDefinitions={
 annuityPaymentTerm:{title:'Compare two invented annuity payment calendars and their recipient rules',fields:[
  ['annuityAnnualCash','Assumed annual payment in each illustrative contract (CAD)',7200,1000,50000,100],
  ['annuityGuaranteeYears','Guaranteed payment years; also the comparison term',10,1,30,1],
  ['annuityDeathYear','Assumed death immediately after this year’s payment',17,1,60,1],
  ['annuityWindow','Whole years included in the displayed receipt totals',25,1,60,1]
 ]}
};
export function annuityGuaranteePlan(d){
 let lifeAnnuitant=0,lifeBeneficiary=0,termAnnuitant=0,termBeneficiary=0;
 const rows=[{x:0,lifeAnnuitant:0,lifeBeneficiary:0,termAnnuitant:0,termBeneficiary:0,lifePayment:0,termPayment:0,lifeTotal:0,termTotal:0}];
 for(let year=1;year<=d.annuityWindow;year++){
  const alive=year<=d.annuityDeathYear,guaranteed=year<=d.annuityGuaranteeYears;
  const la=alive?d.annuityAnnualCash:0,lb=!alive&&guaranteed?d.annuityAnnualCash:0,ta=alive&&guaranteed?d.annuityAnnualCash:0,tb=!alive&&guaranteed?d.annuityAnnualCash:0;
  lifeAnnuitant+=la;lifeBeneficiary+=lb;termAnnuitant+=ta;termBeneficiary+=tb;
  rows.push({x:year,lifeAnnuitant,lifeBeneficiary,termAnnuitant,termBeneficiary,lifePayment:la+lb,termPayment:ta+tb,lifeTotal:lifeAnnuitant+lifeBeneficiary,termTotal:termAnnuitant+termBeneficiary});
 }
 return {rows,end:rows.at(-1),remainingGuaranteed:d.annuityAnnualCash*Math.max(0,d.annuityGuaranteeYears-d.annuityDeathYear)};
}
export function annuityGuaranteeResult(kind,d){
 if(kind!=='annuityPaymentTerm')throw Error('Unknown annuity-payment-term topic.');
 const p=annuityGuaranteePlan(d),checkpoints=[...new Set([1,d.annuityGuaranteeYears,d.annuityGuaranteeYears+1,d.annuityDeathYear,d.annuityDeathYear+1,d.annuityWindow])].filter(y=>y>=1&&y<=d.annuityWindow).sort((a,b)=>a-b);
 return {metrics:[['Life annuity: all recipients’ payments within the window',p.end.lifeTotal,'money'],['Term-certain annuity: all recipients’ payments within the window',p.end.termTotal,'money'],['Full guaranteed instalments remaining after the assumed death',p.remainingGuaranteed,'money']],note:'Two original contract-calendar illustrations share an independently selected annual payment. This does not imply equal purchase premiums, equivalent value, an available quote or an appropriate product choice. Contract A pays for the annuitant’s life, with a guaranteed minimum payment period; if death occurs earlier, a beneficiary receives remaining scheduled guarantee payments. Contract B pays only for that fixed term, with remaining instalments directed to a beneficiary after an earlier death. Payment one occurs at the end of year one; death is assumed immediately after the selected year’s payment. No mortality probabilities or life-expectancy estimates are used. Totals include only the chosen display window, whereas the full remaining-guarantee metric refers to the entire schedule after the assumed death and may extend beyond the window. It is not an immediate lump sum, account balance or additional money to add to already counted receipts. Payments are undiscounted and before tax; purchase prices, inflation, discounting, commutation, cashback, joint-survivor benefits, fees, surrender values and insurer-default protection are not calculated.',charts:[
  {id:'annuity-guarantee-annual-checkpoints',type:'groupbar',title:'A life payment can continue after the guarantee period; a term payment ends',unit:'money',unitLabel:'CAD paid during each selected year · either annuitant or beneficiary',seriesNames:['Life annuity with guaranteed period','Term-certain annuity'],rows:checkpoints.map(year=>({label:'Year '+year,values:[p.rows[year].lifePayment,p.rows[year].termPayment]})),note:'Selected checkpoints include the first year, guarantee end, assumed death, the years immediately following those events, and the display end where they fall inside the window. These are annual payments, not cumulative balances. Payment continues after the life contract’s guarantee end while the annuitant is alive.'},
  {id:'annuity-guarantee-recipients',type:'stackbar',title:'Separate receipts paid during life from guaranteed payments paid after death',unit:'money',seriesNames:['Paid to annuitant within the window','Paid to beneficiary within the window'],rows:[{label:'Life annuity with guaranteed period',values:[p.end.lifeAnnuitant,p.end.lifeBeneficiary]},{label:'Term-certain annuity',values:[p.end.termAnnuitant,p.end.termBeneficiary]}],note:'Components add within each row. They are mutually exclusive recipient assignments for the scheduled payments, not a second payment beside the original. If the assumed death is after the guarantee has expired, no beneficiary guarantee payments remain. A death after the display end produces no beneficiary receipt inside the window.'},
  {id:'annuity-guarantee-cumulative',type:'line',title:'Trace cumulative scheduled receipts without treating them as an investment balance',unit:'money',xLabel:'Completed contract years',series:[{name:'Life annuity: annuitant and beneficiary receipts combined',step:true,rows:p.rows.map(r=>({x:r.x,value:r.lifeTotal}))},{name:'Term-certain annuity: annuitant and beneficiary receipts combined',dash:true,step:true,rows:p.rows.map(r=>({x:r.x,value:r.termTotal}))}],note:'Each step records another scheduled year-end payment. No interest is earned on past receipts, and no purchase premium or spending is subtracted. The curve may flatten after the payment entitlement ends. Receipts outside the displayed window are not included in its endpoint.'},
  {id:'annuity-guarantee-death-matrix',type:'heatmap',title:'Remaining guaranteed instalments depend on the death date and the guaranteed term',unit:'money',unitLabel:'CAD · full scheduled guarantee payments after death; rows: death after year; columns: guaranteed payment years',columns:['5 years','10 years','15 years','20 years'],rows:[1,5,10,15,20].map(deathYear=>({label:'Year '+deathYear,values:[5,10,15,20].map(guaranteeYears=>d.annuityAnnualCash*Math.max(0,guaranteeYears-deathYear))})),note:'Each cell retains the selected annual payment and replaces both dates. It counts the whole remaining guaranteed schedule after the hypothetical death, regardless of the display window. The same minimum-period beneficiary rule is assumed in both examples. Cells are undiscounted instalment sums, not commuted death benefits, purchase prices or mortality-weighted expected values.'}
 ]};
}
